L218:     const onResponse = (event) => {
L219:         const exchange = exchanges.get(event.request);
L220:         if (exchange === undefined)
L221:             return;
L222:         exchanges.delete(event.request);
L223:         try {
L224:             event.response = exchange.respond(event.response);
L225:         }
L226:         catch (cause) {
L227:             throw rejection(cause);
L228:         }
